public class TemperatureReadingTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("ofCelsius(100).toFahrenheit()", 212.0,
                round2(() -> TemperatureReading.ofCelsius(100).toFahrenheit()));
        check("ofFahrenheit(32).toCelsius()", 0.0,
                round2(() -> TemperatureReading.ofFahrenheit(32).toCelsius()));
        check("ofCelsius(0).toKelvin()", 273.15,
                round2(() -> TemperatureReading.ofCelsius(0).toKelvin()));
        check("ofKelvin(300).toCelsius()", 26.85,
                round2(() -> TemperatureReading.ofKelvin(300).toCelsius()));
        check("ofFahrenheit(98.6).toCelsius()", 37.0,
                round2(() -> TemperatureReading.ofFahrenheit(98.6).toCelsius()));
        check("ofFahrenheit(20).isFreezing()", Boolean.TRUE,
                safe(() -> TemperatureReading.ofFahrenheit(20).isFreezing()));
        check("ofCelsius(0.1).isFreezing()", Boolean.FALSE,
                safe(() -> TemperatureReading.ofCelsius(0.1).isFreezing()));
        check("ofCelsius(25).warmerThan(ofFahrenheit(70))", Boolean.TRUE,
                safe(() -> TemperatureReading.ofCelsius(25)
                        .warmerThan(TemperatureReading.ofFahrenheit(70))));
        check("ofKelvin(273.15).warmerThan(ofCelsius(0))", Boolean.FALSE,
                safe(() -> TemperatureReading.ofKelvin(273.15)
                        .warmerThan(TemperatureReading.ofCelsius(0))));
        check("ofCelsius(21.5).toString()", "21.5C",
                safe(() -> TemperatureReading.ofCelsius(21.5).toString()));
        check("ofFahrenheit(212).toString()", "100.0C",
                safe(() -> TemperatureReading.ofFahrenheit(212).toString()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

