public class TemperatureReading {

    private final double celsius;

    private TemperatureReading(double celsius) {
        this.celsius = celsius;
    }

    public static TemperatureReading ofCelsius(double value) {
        return new TemperatureReading(value);
    }

    public static TemperatureReading ofFahrenheit(double value) {
        return new TemperatureReading((value - 32) * 5 / 9);
    }

    public static TemperatureReading ofKelvin(double value) {
        return new TemperatureReading(value - 273.15);
    }

    public double toCelsius() {
        return celsius;
    }

    public double toFahrenheit() {
        return celsius * 9 / 5 + 32;
    }

    public double toKelvin() {
        return celsius + 273.15;
    }

    public boolean isFreezing() {
        return celsius <= 0.0;
    }

    public boolean warmerThan(TemperatureReading other) {
        return celsius > other.celsius;
    }

    @Override
    public String toString() {
        return String.format(java.util.Locale.US, "%.1fC", celsius);
    }
}
